CREATE OR REPLACE FUNCTION public.atlas_apply_direct_sale_payment_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_selected text := nullif(current_setting('atlas.direct_sale_payment_date', true), '');
  v_date date;
  v_registered_at timestamptz := now();
begin
  if new.metadata->>'kind' <> 'direct_sale' or v_selected is null then
    return new;
  end if;
  begin
    v_date := v_selected::date;
  exception when others then
    raise exception 'La fecha del pago no es válida.';
  end;
  if v_date > (now() at time zone 'Europe/Madrid')::date then
    raise exception 'La fecha del pago no puede ser futura.';
  end if;
  new.paid_at := (v_date + (v_registered_at at time zone 'Europe/Madrid')::time)
    at time zone 'Europe/Madrid';
  new.metadata := jsonb_set(
    jsonb_set(
      coalesce(new.metadata, '{}'::jsonb),
      '{sale_local_date}',
      to_jsonb(to_char(new.paid_at at time zone 'Europe/Madrid', 'YYYY-MM-DD')),
      true
    ),
    '{sale_local_time}',
    to_jsonb(to_char(new.paid_at at time zone 'Europe/Madrid', 'HH24:MI')),
    true
  ) || jsonb_build_object(
    'registered_at', v_registered_at,
    'payment_date_selected', true
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.atlas_auto_issue_completed_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  company jsonb;
  patient public.patients%rowtype;
  issuer jsonb;
  recipient jsonb;
  invoice_lines jsonb;
  description text;
  invoice_type text;
begin
  if new.status <> 'completed' or new.cancelled_at is not null or new.deleted_at is not null
     or new.metadata->>'source' <> 'ATLAS Alicante'
     or coalesce(new.metadata->>'migration_source','') <> '' then return new; end if;

  select s.payload into company from public.clinic_settings s
  where s.organization_id=new.organization_id and s.clinic_id=new.clinic_id and s.section='company';
  issuer:=jsonb_build_object(
    'legal_name',trim(coalesce(company->'center'->>'taxName','')),
    'tax_id',trim(coalesce(company->'center'->>'taxId','')),
    'address',trim(coalesce(company->'center'->>'taxAddress',''))
  );
  if nullif(issuer->>'legal_name','') is null or nullif(issuer->>'tax_id','') is null
     or nullif(issuer->>'address','') is null then
    raise exception 'No se puede confirmar el cobro: completa los datos fiscales del centro para generar su factura automática.';
  end if;
  select * into patient from public.patients
  where id=new.patient_id and organization_id=new.organization_id and clinic_id=new.clinic_id and deleted_at is null;
  if not found then raise exception 'No se puede facturar el cobro porque el paciente no está disponible.'; end if;
  recipient:=jsonb_build_object(
    'name',trim(concat_ws(' ',patient.first_name,patient.last_name_1,patient.last_name_2)),
    'tax_id',trim(coalesce(patient.dni_nie,'')),
    'address',trim(concat_ws(', ',nullif(patient.address,''),nullif(patient.postal_code,''),nullif(patient.city,'')))
  );
  invoice_type:=case when nullif(recipient->>'tax_id','') is not null
                          and nullif(recipient->>'address','') is not null then 'F1' else 'F2' end;
  invoice_lines:=new.metadata->'invoice_lines';
  if invoice_lines is null or jsonb_typeof(invoice_lines)<>'array' or jsonb_array_length(invoice_lines)=0 then
    select string_agg(value,' + ') into description
    from jsonb_array_elements_text(coalesce(new.metadata->'services','[]'::jsonb));
    description:=coalesce(nullif(trim(new.metadata->>'payment_label'),''),
      nullif(trim(new.metadata->>'budget_name'),''),nullif(trim(description),''),'Tratamiento de la clínica');
    invoice_lines:=jsonb_build_array(jsonb_build_object(
      'kind','service','description',description,'quantity',1,'total',new.amount
    ));
  end if;
  perform public.atlas_issue_sales_invoice(
    new.organization_id,new.clinic_id,new.id,invoice_type,issuer,
    case when invoice_type='F1' then recipient else '{}'::jsonb end,
    invoice_lines,0,null
  );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.atlas_guard_invoiced_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  old_fixed_metadata jsonb;
  new_fixed_metadata jsonb;
begin
  if not exists (select 1 from public.sales_invoices i where i.payment_id = old.id) then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'El cobro vinculado a una factura emitida no se puede eliminar.';
  end if;

  old_fixed_metadata := coalesce(old.metadata, '{}'::jsonb)
    - 'payment_method_label' - 'payment_method_breakdown'
    - 'payment_method_changed_at' - 'payment_method_changed_by'
    - 'payment_method_history';
  new_fixed_metadata := coalesce(new.metadata, '{}'::jsonb)
    - 'payment_method_label' - 'payment_method_breakdown'
    - 'payment_method_changed_at' - 'payment_method_changed_by'
    - 'payment_method_history';

  if (to_jsonb(new) - 'method' - 'metadata' - 'updated_at')
       is distinct from (to_jsonb(old) - 'method' - 'metadata' - 'updated_at')
     or new_fixed_metadata is distinct from old_fixed_metadata then
    raise exception 'Este cobro ya tiene una factura emitida. Solo se puede corregir la forma de pago.';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.atlas_audit_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare row_data jsonb; org uuid; clinic uuid; rec uuid;
begin
  row_data := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  begin org := nullif(row_data->>'organization_id','')::uuid; exception when others then org := null; end;
  begin clinic := nullif(row_data->>'clinic_id','')::uuid; exception when others then clinic := null; end;
  begin rec := nullif(row_data->>'id','')::uuid; exception when others then rec := null; end;
  insert into public.audit_log(organization_id,clinic_id,actor_id,table_name,record_id,action,metadata)
  values(org,clinic,auth.uid(),tg_table_name,rec,lower(tg_op),jsonb_build_object('source','atlas','transaction_at',now()));
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.atlas_payment_immutable_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_allowed_budget_link boolean := false;
  v_allowed_appointment_link boolean := false;
begin
  if old.receipt_number is distinct from new.receipt_number then
    raise exception 'El número del justificante no se puede modificar' using errcode='22000';
  end if;

  if old.budget_id is null and new.budget_id is not null
     and old.appointment_id is null
     and old.metadata->>'kind'='budget' then
    select exists(
      select 1 from public.budgets b
      where b.id=new.budget_id
        and b.patient_id=old.patient_id
        and b.organization_id=old.organization_id
        and b.clinic_id=old.clinic_id
        and b.deleted_at is null
    ) into v_allowed_budget_link;
  end if;

  if old.appointment_id is null and new.appointment_id is not null
     and old.metadata->>'migration_source'='koibox' then
    select exists(
      select 1 from public.appointments a
      where a.id=new.appointment_id
        and a.patient_id=old.patient_id
        and a.organization_id=old.organization_id
        and a.clinic_id=old.clinic_id
        and a.deleted_at is null
    ) into v_allowed_appointment_link;
  end if;

  if old.patient_id is distinct from new.patient_id
     or (old.budget_id is distinct from new.budget_id and not v_allowed_budget_link)
     or (old.appointment_id is distinct from new.appointment_id and not v_allowed_appointment_link)
     or old.amount is distinct from new.amount
     or old.paid_at is distinct from new.paid_at then
    raise exception 'Los datos económicos de un justificante emitido no se pueden modificar; debe anularse y emitirse uno nuevo' using errcode='22000';
  end if;

  if old.status in ('cancelled','refunded') and new.status is distinct from old.status then
    raise exception 'Un justificante anulado o reembolsado no se puede reactivar' using errcode='22000';
  end if;

  new.updated_at=now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.atlas_queue_meta_conversion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  eligible boolean := false;
  queued_event_name text;
  queued_event_time timestamptz;
begin
  if tg_table_name = 'appointments' then
    if new.deleted_at is not null or new.status in ('cancelled', 'no_show') then
      return new;
    end if;
    if tg_op = 'UPDATE' and old.status not in ('cancelled', 'no_show') then
      return new;
    end if;
    queued_event_name := 'Schedule';
    queued_event_time := coalesce(new.created_at, now());
  elsif tg_table_name = 'payments' then
    if new.deleted_at is not null or new.status <> 'completed' or new.payment_type = 'refund' or new.amount <= 0 then
      return new;
    end if;
    if tg_op = 'UPDATE' and old.status = 'completed' then
      return new;
    end if;
    queued_event_name := 'Purchase';
    queued_event_time := coalesce(new.paid_at, new.created_at, now());
  else
    return new;
  end if;

  select exists (
    select 1
    from public.leads l
    where l.clinic_id = new.clinic_id
      and l.patient_id = new.patient_id
      and l.deleted_at is null
      and l.created_at <= queued_event_time
      and (lower(l.source) = 'meta' or nullif(l.metadata->>'fbclid', '') is not null)
      and (
        l.marketing_consent = true
        or lower(coalesce(l.metadata->>'ads_measurement_consent', '')) in ('true', '1', 'yes', 'on')
        or (
          nullif(l.metadata->'whatsapp_referral'->>'ctwa_clid', '') is not null
          and lower(coalesce(l.metadata->>'ads_measurement_basis', '')) =
            'user_initiated_click_to_whatsapp'
        )
      )
  ) into eligible;

  if eligible then
    insert into public.meta_conversion_outbox (
      organization_id, clinic_id, event_name, source_table, source_id, event_time
    ) values (
      new.organization_id, new.clinic_id, queued_event_name, tg_table_name, new.id, queued_event_time
    ) on conflict (event_name, source_table, source_id) do nothing;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.atlas_keep_payment_receipt_sequence_in_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sequence regclass := pg_get_serial_sequence('public.payments','receipt_number')::regclass;
  v_last bigint;
begin
  if new.receipt_number is null then
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_sequence::text, 0));
  select last_value into v_last from public.payments_receipt_number_seq;
  if new.receipt_number > v_last then
    perform setval(v_sequence, new.receipt_number, true);
  end if;
  return new;
end;
$function$
